### FUNCION: triggerRecalculation
```js
function triggerRecalculation(changedKey) {
    let changedInCycle = true;
    let cycleCount = 0;
    // Safety break: maximum cycles needed is bounded by the number of cells
    const maxCycles = Object.keys(spreadsheetData).length + 1;

    while (changedInCycle && cycleCount < maxCycles) {
        changedInCycle = false;
        cycleCount++;

        for (const key in spreadsheetData) {
            const data = spreadsheetData[key];
            if (data.rawInput && data.rawInput.startsWith('=')) {
                // Store the current calculated value before recalculation attempt
                const oldValue = data.value; 

                calculateAndSetCell(key); 

                // If the calculated value changed, we need another cycle to check dependencies again
                if (spreadsheetData[key].value !== oldValue) {
                    changedInCycle = true;
                }
            }
        }
    }
}
