### FUNCION: initializeSpreadsheet
```js
function initializeSpreadsheet() {
    // Initialize global state variables
    spreadsheetData = {};
    COLUMNS = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
    ROWS = 20;

    // Setup initial data structure and styles for all cells (A1:J20)
    for (let r = 1; r <= ROWS; r++) {
        for (let c = 0; c < COLUMNS.length; c++) {
            const colLetter = COLUMNS[c];
            const key = `${colLetter}${r}`;
            spreadsheetData[key] = {
                value: '',
                style: {}
            };
        }
    }

    // 1. Render the grid structure and attach event listeners to cells
    renderGrid();

    // 2. Attach global format control listener (R5 fix)
    const colorPicker = document.getElementById('background-color-picker');
    if (colorPicker) {
        colorPicker.addEventListener('input', function(e) {
            const newColor = e.target.value;
            // Get the key of the currently selected cell
            const activeKey = getActiveCellKey(); 

            if (activeKey) {
                // Calculate coordinates from the active key
                const colIdx = COLUMNS.indexOf(activeKey[0]);
                const rowNum = parseInt(activeKey.substring(1));

                // Create a mock event object to satisfy handleFormatChange signature
                const mockEvent = { target: { value: newColor } };
                handleFormatChange(mockEvent, activeKey, colIdx, rowNum);
            } else {
                console.warn("No cell selected to apply background color.");
            }
        });
    }

    // 3. Initial state load and rendering
    loadState();
}
