    // Update state style
    spreadsheetData[key].style.backgroundColor = color;

    // Apply to the specific cell element
    updateCellDOM(key, spreadsheetData[key]);

    // FIX: Explicitly apply background color to the DOM element to ensure it overrides any potential rendering bugs in updateCellDOM or subsequent CSS rules.
    const cellElement = getCellElement(colIdx, rowNum);
    if (cellElement) {
        cellElement.style.backgroundColor = color;
    }

    // Save state (R9)
    saveState();
}
