    for (let r = 1; r <= NUM_ROWS; r++) {
        // Selector targets the specific cell element using data attributes
        const selector = `[data-col="${colLetter}"][data-row="${r}"]`;
        const cellElement = document.querySelector(selector);

        if (cellElement) {
            if (isHidden) {
                // Show column: remove hidden class
                cellElement.classList.remove('hidden-col');
            } else {
                // Hide column: add hidden class
                cellElement.classList.add('hidden-col');
            }
        }
    }

    // Toggle visibility for the header itself
    if (isHidden) {
        header.classList.remove('hidden-col');
    } else {
        header.classList.add('hidden-col');
    }

