        const parts = rangeList.split(';').map(p => p.trim());

        for (const part of parts) {
            if (!part) continue;

            if (part.includes(':')) {
                // Handle Range: A1:A3
                const [startKey, endKey] = part.split(':');
                const startCoords = getCellCoordinates(startKey);
                const endCoords = getCellCoordinates(endKey);

                let sumRange = [];
